                    queue.append(literal)

        for clause in clauses:
            add_clause(clause)

        while queue:
            literal = queue.pop()
            if literal > 0:
                neg_literal = -literal
            else:
                neg_literal = -literal

            new_clauses = []
            for clause in clauses:
                if neg_literal in clause:
                    continue
                if -neg_literal in clause:
                    clause.remove(-neg_literal)
                    if not clause:
